__email__ = 'dawid.gwizdz@nokia.com'

import os
import re


class RtgBenchmarkParser(object):
    _re_rtg_schmmi_log_name = re.compile(r'moler\.RTG_SCHMMI_\d+\.raw\.log')
    _cpu_load_log_name = 'moler.RTG_WS_PERIODICAL_CMDS.raw.log'

    def __init__(self, log_dir):
        """
        RTG Benchmark Parser class.

        :param log_dir: Path to directory with moler logs.
        """
        self.schmmi_log_files = [os.path.join(log_dir, f) for f in os.listdir(log_dir)
                                 if re.match(self._re_rtg_schmmi_log_name, os.path.basename(f))]
        self.cpu_load_log_file = os.path.join(
            log_dir, self._cpu_load_log_name) if self._cpu_load_log_name in os.listdir(log_dir) else None
        self.tti_process_benchmarks = {}
        self.tti_len_benchmarks = {}
        self.cpu_load_benchmarks = {}

    def get_rtg_benchmarks(self):
        """
        Get RTG benchmarks.

        :return: Dictionary with benchmarks.
        """
        if self.schmmi_log_files:
            self.parse_schmmi_logs()
        if self.cpu_load_log_file:
            self.parse_cpu_load_logs()
        benchmarks = {'TTI Start Avg': self.tti_process_benchmarks, 'TTI Length Avg': self.tti_len_benchmarks,
                      'CPU Load': self.cpu_load_benchmarks}
        return benchmarks

    def parse_schmmi_logs(self):
        for schmmi_log_file in self.schmmi_log_files:
            ctrl = 'CTRL-{}'.format(re.search(r'\d', schmmi_log_file).group().zfill(2))
            with open(schmmi_log_file, 'r') as f:
                result = self._parse_schmmi_log_file(f)
                self.tti_process_benchmarks[ctrl] = result['TTI_START']
                self.tti_len_benchmarks[ctrl] = result['TTI_LENGTH']

    # Example line: Avg: 11 (6315 samples)
    _re_avg = re.compile(r'Avg: (?P<AVG>\d+)')

    def _parse_schmmi_log_file(self, schmmi_log_file):
        count = {'TTI_START': 0, 'TTI_LENGTH': 0}
        avg_sum = {'TTI_START': 0.0, 'TTI_LENGTH': 0.0}
        key = ''
        for line in schmmi_log_file:
            match_result = re.match(self._re_avg, line)
            if match_result:
                avg_addend = float(match_result.group('AVG'))
                count[key] += 1
                avg_sum[key] += avg_addend
            elif "TTI processing end" in line:
                key = 'TTI_START'
            elif "TTI length" in line:
                key = 'TTI_LENGTH'
        avg = {'TTI_START': round(avg_sum['TTI_START'] / count['TTI_START'] if count['TTI_START'] != 0 else 0.0, 2),
               'TTI_LENGTH': round(avg_sum['TTI_LENGTH'] / count['TTI_LENGTH'] if count['TTI_LENGTH'] != 0 else 0.0, 2)}
        return avg

    # Example line: CTRL-01 10.0.2.11       CORE-1    Average CPU load:   1.60% (Min:   1.60% Max:   1.62%)
    _re_cpu_load = re.compile(
        r'(?P<CTRL>CTRL-\d+)\s*\d+\.\d+\.\d+\.\d+\s*(?P<CORE>CORE-\d)\s*Average CPU.? load:\s*'
        r'(?P<AVG>\d+.\d+)%\s*\(Min:\s*(?P<MIN>\d+.\d+)%\s*Max:\s*(?P<MAX>\d+.\d+)%\)')

    def parse_cpu_load_logs(self):
        count = {}
        avg_sum = {}
        min_load = {}
        max_load = {}
        with open(self.cpu_load_log_file) as f:
            for line in f:
                search_result = re.search(self._re_cpu_load, line)
                if search_result:
                    ctrl = search_result.group('CTRL')
                    core = search_result.group('CORE')
                    key = (ctrl, core)
                    count[key] = count.setdefault(key, 0) + 1
                    avg_addend = float(search_result.group('AVG'))
                    avg_sum[key] = avg_sum.setdefault(key, 0.0) + avg_addend
                    min_load[key] = float(search_result.group('MIN'))
                    max_load[key] = float(search_result.group('MAX'))
        for key in count:
            self.cpu_load_benchmarks.setdefault(key[0], {})[key[1]] = {'AVG': round(avg_sum[key] / count[key], 2),
                                                                       'MIN': min_load[key],
                                                                       'MAX': max_load[key]}
